const assert = require('node:assert/strict');
const merge = require('./index.js');
const payload = JSON.parse('{"__proto__":{"isAdmin":true}}');
const plain = merge({ a: 1 }, payload);
assert.equal(plain.isAdmin, undefined);
assert.equal(Object.getPrototypeOf(plain), Object.prototype);
const nullPrototype = merge(Object.create(null), payload);
assert.equal(nullPrototype.isAdmin, undefined);
assert.equal(Object.getPrototypeOf(nullPrototype), Object.prototype);
const nested = merge({ session: null }, JSON.parse('{"session":{"__proto__":{"isAdmin":true}}}'));
assert.equal(nested.session.isAdmin, undefined);
assert.equal(Object.getPrototypeOf(nested.session), Object.prototype);
const sourceAsTarget = merge(JSON.parse('{"__proto__":{"isAdmin":true}}'), {});
assert.equal(sourceAsTarget.isAdmin, undefined);
assert.equal(Object.getPrototypeOf(sourceAsTarget), Object.prototype);
assert.deepEqual(merge({nested:{a:1},arr:[1]}, {nested:{b:2},arr:[2]}), {nested:{a:1,b:2},arr:[1,2]});
assert.deepEqual(merge.all([{a:1},{b:2}]),{a:1,b:2});
assert.equal({}.isAdmin, undefined);
console.log('security-patched deepmerge regression tests passed');
